    "A cada 30 minutos": "Her 30 dakikada",
    "A cada 45 minutos": "Her 45 dakikada",
    "A cada 60 minutos": "Her 60 dakikada",
    "Recarregar reinicia a conexão de cada rede e": "Yenileme her ağın bağlantısını yeniden başlatır ve",
    "busca de volta os comentários que a plataforma ainda guarda": "platformun hâlâ sakladığı yorumları geri getirir",
    "— é assim que o buraco deixado por um engasgo da conexão se fecha sozinho. As redes são recarregadas uma de cada vez, com folga entre elas. Cada coluna também tem um botão 🔄 para recarregar só ela, na hora que você quiser.": "— bağlantıdaki bir aksamanın bıraktığı boşluk böyle kendiliğinden kapanır. Ağlar teker teker, aralarında biraz bekleyerek yenilenir. Her sütunun ayrıca sadece kendisini istediğiniz an yenilemek için bir 🔄 düğmesi vardır.",
    "Recarregar todas as redes conectadas e buscar os comentários antigos de volta": "Bağlı tüm ağları yenile ve eski yorumları geri getir",
    "Recarregar esta rede e buscar os comentários antigos de volta": "Bu ağı yenile ve eski yorumları geri getir",
