    "Ajustes do widget 🕐 do painel. A aparência (cores, tamanho, posição, animações) fica no": "Paneldeki 🕐 widget’ının ayarları. Görünümü (renkler, boyut, konum, animasyonlar)",
    "🧩 Personalizar widgets": "🧩 Widget’ları özelleştir",
    "logo acima, escolhendo \"🕐 Relógio / cronômetro / timer\".": "hemen yukarıda, \"🕐 Saat / kronometre / zamanlayıcı\" seçilerek ayarlanır.",
    "🌍 Fuso horário": "🌍 Saat dilimi",
    "\"Do computador\" segue o relógio do Windows. Escolha outro fuso se você transmite para um público de outro país — o relógio da tela usa o fuso escolhido.": "\"Bilgisayardan\" Windows saatini izler. Başka bir ülkedeki izleyicilere yayın yapıyorsanız başka bir dilim seçin — ekrandaki saat seçilen dilimi kullanır.",
    "🔊 Som quando o timer acabar": "🔊 Zamanlayıcı bittiğindeki ses",
