    "📢 Tirar o Aviso da tela automaticamente (Timer e Avisos trabalhando juntos)": "📢 Duyuruyu ekrandan otomatik kaldır (Zamanlayıcı ve Duyurular birlikte çalışır)",
    "✨ Piscar o número quando zerar": "✨ Sıfıra ulaşınca sayıyı yanıp söndür",
    "📅 Mostrar a data junto da hora no painel (desligado = só a hora)": "📅 Panelde tarihi saatin yanında göster (kapalı = sadece saat)",
    "⏳ Reta final do timer (antes de zerar)": "⏳ Zamanlayıcının son düzlüğü (sıfırdan önce)",
    "✨ Piscar o número na reta final": "✨ Son düzlükte sayıyı yanıp söndür",
    "Começa a quantos segundos do fim (1 a 60)": "Bitişe kaç saniye kala başlar (1 ile 60 arası)",
    "Cor da reta final": "Son düzlük rengi",
    "🔴 Quando o tempo acabar (no 00:00)": "🔴 Süre dolduğunda (00:00’da)",
    "Pisca por quantos segundos (0 = sem parar; máx. 300)": "Kaç saniye yanıp söner (0 = hiç durmaz; en fazla 300)",
    "Cor da piscada do fim": "Bitiş yanıp sönmesinin rengi",
    "📢 O Aviso piscando junto com o timer": "📢 Duyurunun zamanlayıcıyla birlikte yanıp sönmesi",
    "📢 Piscar o Aviso na tela na reta final": "📢 Son düzlükte ekrandaki Duyuruyu yanıp söndür",
    "Cor do Aviso enquanto pisca": "Yanıp sönerken Duyurunun rengi",
    "O ↺ da cor do Aviso tira a troca de cor: ele pisca mantendo a cor normal do texto.": "Duyuru rengindeki ↺ renk değişimini kaldırır: metnin normal rengini koruyarak yanıp söner.",
    "O que acontece na tela quando você clica em 🎲": "🎲 tuşuna bastığınızda ekranda ne olur",
    "Sortear": "Çekiliş yap",
    ". As fichas extras de subs e membros ficam no próprio botão 🎁 do painel; a aparência do pódio fica no": ". Sub’lar ve üyeler için ek biletler 🎁 düğmesinin içindedir; podyumun görünümü şurada:",
    ", escolhendo \"🎁 Sorteio\".": ", \"🎁 Çekiliş\" seçilerek.",
    "🎲 Tempo que o dado fica rodando na tela (0 a 15 segundos)": "🎲 Zarın ekranda dönme süresi (0 ile 15 saniye arası)",
    "É o suspense antes do pódio aparecer.": "Podyum görünmeden önceki merak anıdır.",
    "vai direto para os ganhadores, sem dado.": "doğrudan kazananlara geçer, zar olmadan.",
    "🔊 Som do dado": "🔊 Zar sesi",
    "🎲 Dado padrão do OBS Social": "🎲 OBS Social varsayılan zarı",
    "Quicar e cair (bounce)": "Zıpla ve düş",
    "Rodopiar sem parar": "Durmadan dön",
    "Desfocar e voltar": "Bulanıklaş ve dön",
    "Chacoalhar": "Sarsıl",
    "Texto do comentário ao lado do nome": "Yorum metni ismin yanında",
    "(desligado = embaixo do nome, como sempre foi)": "(kapalı = ismin altında, hep olduğu gibi)",
    "É o mesmo formato do 💬 Chat ao vivo fixo: o nome e o comentário na mesma linha, com o horário à direita. Vale para a aba Ao vivo, para as colunas e para as outras listas do painel.": "💬 Sabit canlı sohbetle aynı düzen: isim ve yorum aynı satırda, saat sağda. Canlı sekmesi, sütunlar ve panelin diğer listeleri için geçerlidir.",
    "📄 Texto do comentário embaixo do nome (igual ao painel ao vivo)": "📄 Yorum metni ismin altında (canlı panel gibi)",
    "🔐 O navegador diz \"a conexão com este site não é segura\". Isso é problema?": "🔐 Tarayıcı \"bu siteyle bağlantınız güvenli değil\" diyor. Bu bir sorun mu?",
    "Não é problema.": "Sorun değil.",
    "Esse recado aparece em todo endereço que começa com \"http://\" e não quer dizer que alguém esteja bisbilhotando o seu painel.": "Bu uyarı \"http://\" ile başlayan her adreste çıkar ve birinin panelinizi gözetlediği anlamına gelmez.",
    "No seu computador (localhost):": "Kendi bilgisayarınızda (localhost):",
    "os navegadores tratam o localhost como origem confiável por definição. Esses dados nunca saem da máquina — não passam por cabo, Wi-Fi nem internet. O aviso ali é só o texto padrão do \"http://\".": "tarayıcılar localhost’u tanımı gereği güvenilir kaynak sayar. Bu veriler makineden hiç çıkmaz — ne kablo, ne Wi-Fi, ne internet. Oradaki uyarı yalnızca \"http://\" için standart metindir.",
    "No endereço da sua rede (192.168...):": "Ağ adresinizde (192.168...):",
    "os dados andam apenas entre o seu computador e o aparelho do seu mod, passando pelo seu roteador. Nada disso vai para a internet.": "veriler yalnızca bilgisayarınızla modunuzun cihazı arasında, kendi modeminizden geçerek dolaşır. Hiçbiri internete gitmez.",
    "Por que o OBS Social não usa \"https\"?": "OBS Social neden \"https\" kullanmıyor?",
    "O cadeado do https depende de um certificado, e certificado de verdade só é emitido para um nome de site público, como \"seusite.com.br\". Um endereço caseiro de rede não tem nome público — e nem deveria ter, porque ele não existe fora da sua casa.": "https kilidi bir sertifikaya bağlıdır ve gerçek sertifika yalnızca \"siteniz.com\" gibi herkese açık bir site adına verilir. Ev ağı adresinin herkese açık bir adı yoktur — olmamalı da, çünkü evinizin dışında var olmaz.",
    "E um certificado feito em casa?": "Peki ev yapımı bir sertifika?",
    "Seria pior: o navegador passaria a mostrar uma tela vermelha de perigo toda vez, em cada aparelho, e para tirá-la você teria que instalar um arquivo de confiança no sistema — exatamente o tipo de coisa que faz o antivírus apitar. Por isso o OBS Social não faz isso.": "Daha kötü olurdu: tarayıcı her seferinde ve her cihazda kırmızı bir tehlike ekranı gösterirdi; bunu kaldırmak için sisteme bir güven dosyası kurmanız gerekirdi — tam da antivirüsü alarma geçiren türden bir şey. OBS Social bu yüzden bunu yapmaz.",
    "O que realmente protege você aqui": "Sizi burada gerçekten koruyan şey",
    "é o que está logo abaixo: o programa só aceita conexões da sua própria rede, você escolhe o que a rede pode usar e ainda pode colocar uma senha.": "hemen aşağıda duruyor: program yalnızca kendi ağınızdan gelen bağlantıları kabul eder, ağın neyi kullanabileceğini siz seçersiniz ve üstüne bir parola koyabilirsiniz.",
    "🔟 Mostrar os décimos de segundo no cronômetro (00:05.4)": "🔟 Kronometrede saniyenin onda birini göster (00:05.4)",
    "🔇 Clique aqui para liberar o som dos alertas": "🔇 Uyarı sesine izin vermek için buraya tıklayın",
    "🔇 Toque aqui para liberar o som dos alertas": "🔇 Uyarı sesine izin vermek için buraya dokunun",
    "O navegador só toca som depois de um clique na página": "Tarayıcı sesi ancak sayfaya tıklandıktan sonra çalar",
    "Toque uma vez para o navegador liberar o som": "Tarayıcının sese izin vermesi için bir kez dokunun",
    "Se o navegador disser \"não é seguro\", é só porque o endereço é da sua rede e não da internet — a explicação completa está em ⚙️ Configurações → 🔗 URLs para o OBS.": "Tarayıcı \"güvenli değil\" diyorsa, bu yalnızca adresin internete değil kendi ağınıza ait olmasındandır — tam açıklama ⚙️ Ayarlar → 🔗 OBS için URL’ler bölümünde.",
    "🎨 Temas": "🎨 Temalar",
