    "Não consegui ler esse arquivo de tema. Ele precisa ser um tema salvo pelo OBS Social.": "Bu tema dosyasını okuyamadım. OBS Social ile kaydedilmiş bir tema olmalı.",
    "Carregar este tema? Ele substitui as cores e os ajustes de aparência que estão valendo agora.": "Bu tema yüklensin mi? Şu anda geçerli olan renkleri ve görünüm ayarlarını değiştirir.",
