    'Idioma da interface': 'Arayüz dili',
    'Escolha o idioma do OBS Social. "Idioma do sistema" segue o idioma do navegador/computador de quem abre cada página. A mudança vale para o painel, as configurações e os overlays — na hora, sem reiniciar.':
      'OBS Social’ın dilini seç. "Sistem dili", her sayfayı açan kişinin tarayıcı/bilgisayar dilini takip eder. Değişiklik panel, ayarlar ve overlay’ler için anında geçerli olur — yeniden başlatmadan.',
    'O que não tiver tradução aparece em português. Textos escritos por você ou pelos espectadores (nomes, mensagens do chat, títulos dos widgets) nunca são traduzidos.':
      'Çevirisi olmayan her şey Portekizce görünür. Senin veya izleyicilerin yazdığı metinler (adlar, sohbet mesajları, widget başlıkları) asla çevrilmez.',

