      'Şifre varsa, paneli ağdan açan herkes onunla giriş yapıp her şeyi kontrol edebilir (yukarıdaki anahtarlar giriş YAPMAYANLAR için geçerlidir). Şifre karıştırılmış bir koda (hash) dönüşür — asla düz metin olarak saklanmaz. Yalnızca bu bilgisayar belirleyebilir, değiştirebilir veya kaldırabilir.',
    'senha atual (para trocar/remover)': 'mevcut şifre (değiştirmek/kaldırmak için)',
    'nova senha (mín. 4 caracteres)': 'yeni şifre (en az 4 karakter)',
    'Definir/trocar a senha': 'Şifreyi belirle/değiştir',
    'Remover a senha': 'Şifreyi kaldır',
    'A senha precisa ter pelo menos 4 caracteres.': 'Şifre en az 4 karakter olmalı.',
    'Remover a senha? A rede volta a poder usar só o que os seletores liberarem.': 'Şifre kaldırılsın mı? Ağ yeniden yalnızca anahtarların izin verdiklerini kullanabilir.',
    'Desligar a restrição = LIBERDADE TOTAL. Qualquer pessoa na sua rede/Wi-Fi vai poder controlar o programa inteiro, sem senha. Tem certeza?':
      'Kısıtlamayı kapatmak = TAM SERBESTLİK. Ağındaki/Wi-Fi’ndaki herkes tüm programı şifresiz kontrol edebilecek. Emin misin?',
    '🔒 Modo seguro: quem entra pela rede só assiste ao painel e usa o que você liberar nos seletores abaixo.': '🔒 Güvenli mod: ağdan girenler yalnızca paneli izler ve aşağıdaki anahtarlarda izin verdiklerini kullanır.',
    '⚠️ Liberdade total: qualquer pessoa conectada na sua rede/Wi-Fi controla o programa inteiro, sem senha. Use só em redes que você confia de verdade.':
      '⚠️ Tam serbestlik: ağına/Wi-Fi’na bağlı herkes tüm programı şifresiz kontrol eder. Yalnızca gerçekten güvendiğin ağlarda kullan.',
    '🖥️ Máquinas conectadas agora': '🖥️ Şu an bağlı makineler',
    'ninguém conectado': 'kimse bağlı değil',
    'Só este computador está conectado agora — ninguém mais está acessando.': 'Şu an yalnızca bu bilgisayar bağlı — başka erişen yok.',
    'aparelho desconhecido': 'bilinmeyen cihaz',
    'não encontrei um IP de rede neste computador': 'bu bilgisayarda bir ağ IP’si bulamadım',
    'Reiniciar o OBS Social agora? Ele fecha e abre sozinho em alguns segundos; o overlay no OBS reconecta sem você fazer nada.':
      'OBS Social şimdi yeniden başlatılsın mı? Birkaç saniye içinde kendiliğinden kapanıp açılır; OBS’deki overlay sen hiçbir şey yapmadan yeniden bağlanır.',
    '♻️ Reiniciando o OBS Social... esta página recarrega em instantes.': '♻️ OBS Social yeniden başlatılıyor... bu sayfa birazdan yenilenecek.',
