    "O botão 🖱️ do painel abre esta página direto. Tudo salva sozinho e muda na tela na hora, até no meio da live. O 🧪 coloca um comentário de exemplo no ar para você ver o destaque — ele aparece no OBS também, então tire do ar antes de ir para a live.": "Panelin 🖱️ düğmesi bu sayfayı doğrudan açar. Her şey kendiliğinden kaydedilir ve ekranda anında değişir, yayının ortasında bile. 🧪 öne çıkarmayı görebilmeniz için yayına örnek bir yorum koyar — OBS’de de görünür, bu yüzden yayına çıkmadan önce kaldırın.",

