    "Voltar (desfaz o último ajuste do Organizar: posição, tamanho, camada, peça, arte... — Ctrl+Z)": "Geri (Ekranı Düzenle'deki son ayarı geri alır: konum, boyut, katman, parça, tasarım... — Ctrl+Z)",
