    "TUDO do Organizar de volta ao padrão de fábrica: posições, tamanhos, camadas, peças e arte (dá para desfazer)": "Ekranı Düzenle'deki HER ŞEY fabrika ayarına döner: konumlar, boyutlar, katmanlar, parçalar ve tasarım (geri alınabilir)",
    "→ \"Fundo do comentário em destaque\". Assim que ela é ativada, aparece a peça": "→ \"Öne çıkan yorumun arka planı\". Etkinleşir etkinleşmez şu parça olarak belirir:",
    "dentro do Destaque no 🖱️": "Öne Çıkan kartının içinde, 🖱️",
    "(e nas Camadas) — arraste, estique, gire e escolha o encaixe dela por lá, com ou sem o 🧩 ligado. A receita para a arte virar o cartão INTEIRO:": "(ve Katmanlar'da) — orada sürükleyin, esnetin, döndürün ve yerleşimi seçin, 🧩 açık ya da kapalı. Tasarımın kartın TAMAMI olması için tarif:",
    "— e você arrasta cada peça para o lugar certo dela.": "— ve her parçayı yerine siz sürüklersiniz.",
    "do Organizar a tela para ver. Assim que a arte é ativada, ela vira a peça": "(Ekranı Düzenle içinde). Tasarım etkinleşir etkinleşmez şu parçaya dönüşür:",
    "— dá para arrastar, esticar, girar e escolher o encaixe, como qualquer outra peça. E para a arte virar o cartão inteiro (sem o fundo padrão, com cada peça onde você quiser), ligue": "— sürükleyebilir, esnetebilir, döndürebilir ve yerleşimi seçebilirsiniz, diğer parçalar gibi. Tasarımın kartın tamamı olması için (varsayılan arka plan olmadan, her parça istediğiniz yerde) şunları açın:",

