    "(grava assim que algo muda) ou um relógio de 1s a 24h — e o OBS Social copia o item para a pasta escolhida, numa sub-pasta com data e hora. O": "(bir şey değişir değişmez kaydeder) ya da 1sn–24sa arası bir saat — OBS Social öğeyi seçtiğiniz klasöre, tarih-saatli bir alt klasöre kopyalar.",
    "↩️ Restaurar": "↩️ Geri yükle",
    "traz de volta o backup que você escolher. Um backup agendado só grava quando algo mudou de verdade, e os 30 mais recentes de cada item ficam guardados.": "seçtiğiniz yedeği geri getirir. Planlı yedek yalnızca gerçekten bir şey değiştiğinde yazar; her öğenin en yeni 30 yedeği saklanır.",
