    "Os arquivos de cada dia de live. Sem eles, um reinício não recupera o chat nem o sorteio do dia.": "Her yayın gününün dosyaları. Onlar olmadan yeniden başlatma, günün sohbetini ve çekilişini geri getiremez.",
