    "Quais comentários já foram para a tela e os que estão guardados na aba 📥 Fila.": "Hangi yorumların ekrana çıktığı ve 📥 Kuyruk sekmesinde saklananlar.",
    "🎁 Participantes do sorteio": "🎁 Çekiliş katılımcıları",
    "A lista de quem comentou e concorre no sorteio.": "Yorum yapan ve çekilişe katılanların listesi.",
