    "Os canais lembrados de cada rede (o programa para de reconectar sozinho ao abrir).": "Her ağın hatırlanan kanalları (program açılışta kendiliğinden bağlanmayı bırakır).",
    "🧰 QR codes e winstreaks": "🧰 QR kodlar ve winstreakler",
