    "os itens acima": "öğelerin tümü",
    "devolve todas as configurações ao estado original (cores, posições, widgets, idioma, Labs...). É como reinstalar o programa. Sua senha de acesso pela rede é mantida, para você não ficar trancado fora — removê-la é uma opção separada, em 🔗 URLs para o OBS.": "tüm ayarları ilk hâline döndürür (renkler, konumlar, widgetlar, dil, Labs...). Programı yeniden kurmak gibidir. Ağ erişim şifreniz korunur, dışarıda kalmayın diye — kaldırmak ayrı bir seçenek, 🔗 OBS için URL’lerde.",
