    "Deixe o OBS Social com a sua cara: cores, imagem de fundo, tamanhos de texto e de ícones, cantos e espaçamento. Isto muda o": "OBS Social’a kendi tarzınızı verin: renkler, arka plan resmi, metin ve simge boyutları, köşeler ve boşluklar. Bu şunu değiştirir:",
