    "— ao carregar um tema, o cartão do destaque, o chat fixo e os widgets ganham as cores, os cantos e a fonte dele (o QR mantém o fundo branco, para continuar escaneável)": "— bir tema yüklenince öne çıkan kart, sabit sohbet ve widgetlar onun renklerini, köşelerini ve yazı tipini alır (QR, taranabilir kalması için beyaz arka planını korur)",
