    "Recursos para o OBS Social funcionar bem para todo mundo. Cada um tem o seu liga/desliga e vale no": "OBS Social’ın herkes için iyi çalışması için özellikler. Her birinin kendi anahtarı var ve şurada geçerli:",
    "painel e nas configurações": "panel ve ayarlar",
    "na hora, em todos os aparelhos conectados. Os overlays do OBS (o conteúdo que o público vê) ficam como você desenhou.": "anında, bağlı tüm cihazlarda. OBS overlayleri (izleyicinin gördüğü içerik) tasarladığınız gibi kalır.",
    "Contraste reforçado": "Güçlü kontrast",
    "— textos secundários e bordas deixam de ser suaves; links ganham sublinhado": "— ikincil metinler ve kenarlıklar yumuşak olmaktan çıkar; bağlantıların altı çizilir",
    "Para baixa visão. Combina com o tema ⚡ Alto contraste da aba 🎨 Temas (preto + amarelo), que muda as cores da interface inteira.": "Az görenler için. 🎨 Temalar sekmesindeki ⚡ Yüksek kontrast temasıyla (siyah + sarı) birleşir; o, tüm arayüzün renklerini değiştirir.",
    "Reduzir animações": "Animasyonları azalt",
    "— corta as animações e transições da interface": "— arayüzün animasyonlarını ve geçişlerini keser",
    "Para quem tem sensibilidade a movimento (enjoo, epilepsia fotossensível, TDAH). As animações do overlay na live não mudam — elas são parte do seu show.": "Harekete duyarlılık için (mide bulantısı, ışığa duyarlı epilepsi, DEHB). Yayındaki overlay animasyonları değişmez — onlar şovunuzun parçası.",
    "Foco visível reforçado": "Güçlü görünür odak",
    "— um anel grosso mostra onde você está ao navegar por Tab": "— kalın bir halka, Tab ile gezinirken nerede olduğunuzu gösterir",
    "Para quem usa o teclado em vez do mouse (mobilidade reduzida, leitores de tela).": "Fare yerine klavye kullananlar için (kısıtlı hareket, ekran okuyucular).",
    "Formas além de cor no status": "Durumda renkten fazlası: şekiller",
    "— a bolinha das conexões ganha ✓ (live no ar), ! (sem live) e ✕ (falhou)": "— bağlantı noktası ✓ (yayın açık), ! (yayın yok) ve ✕ (başarısız) kazanır",
    "Para daltonismo: verde, amarelo e vermelho deixam de ser a única pista.": "Renk körlüğü için: yeşil, sarı ve kırmızı tek ipucu olmaktan çıkar.",
    "💡 Também ajudam (já existem em outras abas)": "💡 Bunlar da yardımcı olur (başka sekmelerde zaten var)",
    "(no painel) amplia tudo de uma vez; o": "(paneldeki) her şeyi tek seferde büyütür;",
    "Tamanho dos textos": "Metin boyutu",
    "e a": "ve",
    "fonte": "yazı tipi",
    "ficam na aba 🎨 Temas; os avisos importantes aparecem como texto (nunca só como som); e as dicas dos botões são lidas por leitores de tela. Falta algo para você? Conte na aba 📣 Feedback — acessibilidade é prioridade.": "🎨 Temalar sekmesindedir; önemli uyarılar metin olarak görünür (asla yalnızca ses değil); düğme ipuçlarını ekran okuyucular okur. Eksik bir şey mi var? 📣 Geri bildirim sekmesinde anlatın — erişilebilirlik önceliktir.",
    "A conexão falhou": "Bağlantı başarısız oldu",
    "🎁 Resultado do sorteio": "🎁 Çekiliş sonucu",
