    "que chega": "animasyonlanır",
    "anima — os que já estavam na tela ficam parados. Com ♿ Acessibilidade → Sem animações ligado, nada anima.": "— ekranda olanlar yerinde durur. ♿ Erişilebilirlik → Animasyonsuz açıkken hiçbir şey animasyonlanmaz.",
    "Tudo apagado: o OBS Social voltou ao padrão de fábrica e vai REINICIAR sozinho em instantes (pelo mesmo caminho da atualização). Esta página recarrega quando ele voltar.": "Her şey silindi: OBS Social fabrika ayarına döndü ve birazdan kendi kendine YENİDEN BAŞLAYACAK (güncellemeyle aynı yoldan). O dönünce bu sayfa yenilenir.",
    "Ao terminar, o programa REINICIA sozinho (como na atualização)": "Bitince program kendi kendine YENİDEN BAŞLAR (güncellemedeki gibi)",
    "Este é o MESMO pódio da tela do OBS (widget 🎁), com o mesmo dado 🎲 e as mesmas configurações — o suspense aqui é o do seu público. Fechar no ✖ acima não tira da tela.": "Bu, OBS ekranındaki podyumun TA KENDİSİ (🎁 widget’ı), aynı zar 🎲 ve aynı ayarlarla — buradaki heyecan seyircininkiyle aynı. Üstteki ✖ yalnız burada kapatır, ekrandan kaldırmaz.",
    "✖ Tirar o pódio da tela": "✖ Podyumu ekrandan kaldır",
