    "Organizar a tela: posições, tamanhos e mídias (abre as configurações, aba 🎨 Temas)": "Ekranı düzenle: konumlar, boyutlar ve medya (ayarları açar, 🎨 Temalar sekmesi)",
    "Escreva um recado para aparecer na tela da live. A aparência (fonte, cores, tamanho, animações) fica em": "Yayın ekranında görünecek bir not yazın. Görünüm (yazı tipi, renkler, boyut, animasyonlar) şurada:",
    "Configurações → 🎨 Temas": "Ayarlar → 🎨 Temalar",
    "O fuso horário fica em": "Saat dilimi şurada:",
    "Estas opções também estão em Configurações → 🎨 Temas, junto da escolha do som.": "Bu seçenekler Ayarlar → 🎨 Temalar’da, ses seçiminin yanında da var.",
    "Se o ⏳ Timer estiver combinado com os Avisos, o recado sai sozinho quando o tempo acabar.": "⏳ Zamanlayıcı Duyurularla eşliyse, süre bitince not kendiliğinden gider.",
