    ", marque": ", işaretleyin:",
    "Ativar servidor WebSocket": "WebSocket sunucusunu etkinleştir",
    "e copie a senha para cá. A conversa é toda dentro do seu computador — nada passa pela internet.": "ve şifreyi buraya kopyalayın. Tüm konuşma bilgisayarınızın içinde kalır — hiçbir şey internetten geçmez.",
    "Porta (a do OBS — padrão 4455)": "Port (OBS’inki — varsayılan 4455)",
    "Senha do servidor WebSocket": "WebSocket sunucu şifresi",
    "⚪ desligado (ligue o seletor acima)": "⚪ kapalı (yukarıdaki anahtarı açın)",
    "A senha fica guardada só neste computador (na pasta": "Şifre yalnızca bu bilgisayarda saklanır (şu klasörde:",
    ") e nunca é enviada às telas. Quem acessa o painel pela rede só comanda o OBS se você liberar o seletor 🎬 no modo restrito (aba 🔒 Segurança) — de fábrica, fica bloqueado.": ") ve ekranlara asla gönderilmez. Paneli ağdan açanlar, kısıtlı modda 🎬 seçicisini açarsanız OBS’i yönetebilir (🔒 Güvenlik sekmesi) — fabrikadan kilitli.",
    "a que o OBS mostra": "OBS’in gösterdiği",
    "Salvar e conectar": "Kaydet ve bağlan",
    "🎵 Mesa de trilhas (experimental)": "🎵 Parça masası (deneysel)",
    "— botões de músicas e efeitos no painel; o som toca na live (pelo overlay no OBS), no painel, ou nos dois": "— panelde müzik ve efekt düğmeleri; ses yayında (OBS’teki overlay üzerinden), panelde veya ikisinde çalar",
    "Cada trilha é um botão na ferramenta 🎵 do painel (e do celular na mesma rede).": "Her parça, panelin 🎵 aracında bir düğmedir (ve aynı ağdaki telefonda).",
    "Uma por vez": "Aynı anda bir tane",
    ": apertar outra troca com fade; BGM pode repetir (🔁); o ⏹ para tudo. Para o som entrar NA LIVE, a fonte do overlay no OBS precisa estar com o áudio ativo (é o normal de uma fonte de navegador).": ": başkasına basmak fade ile değiştirir; BGM tekrarlayabilir (🔁); ⏹ her şeyi durdurur. Sesin YAYINA girmesi için OBS’teki overlay kaynağının sesi açık olmalı (tarayıcı kaynağında normaldir).",
    "🎛️ Importar do Stream Deck (backup de perfis)": "🎛️ Stream Deck’ten içe aktar (profil yedeği)",
    "No programa Stream Deck:": "Stream Deck programında:",
    "Preferências → Perfis → exportar backup": "Tercihler → Profiller → yedeği dışa aktar",
    ". Os botões \"Tocar áudio\" viram trilhas prontas (nome, grupo, volume, 🔁 e fade). Os arquivos de som não vêm no backup — aponte a pasta deles aqui embaixo que eu encontro e copio sozinho.": ". \"Ses Çal\" düğmeleri hazır parçalara dönüşür (ad, grup, ses, 🔁 ve fade). Ses dosyaları yedekte gelmez — klasörlerini aşağıda gösterin, ben bulur ve kopyalarım.",
    "Enviar um arquivo de som para virar trilha": "Parça olacak bir ses dosyası yükle",
    "Adicionar uma trilha com um som já enviado": "Zaten yüklenmiş bir sesle parça ekle",
    "Emoji do botão": "Düğme emojisi",
    "Nome da trilha": "Parça adı",
    "Grupo (pasta)": "Grup (klasör)",
    "Trilhas do mesmo grupo ficam juntas na mesa": "Aynı gruptaki parçalar masada birlikte durur",
    "Cor do botão": "Düğme rengi",
    "Remover esta trilha": "Bu parçayı kaldır",
    "O arquivo de som desta trilha (envie novos no campo acima)": "Bu parçanın ses dosyası (yenilerini yukarıdaki alandan yükleyin)",
    "— escolher o som —": "— sesi seç —",
    "Fade (segundos) na entrada, na troca e no ⏹": "Fade (saniye): girişte, geçişte ve ⏹’da",
    "Repetir sem parar (BGM)": "Durmadan tekrarla (BGM)",
    "Onde esta trilha toca": "Bu parça nerede çalar",
    "📡 Na live": "📡 Yayında",
    "🖥️ Só no painel": "🖥️ Sadece panelde",
    "📡+🖥️ Nos dois": "📡+🖥️ İkisinde",
    "Procurar os sons das trilhas pendentes nessa pasta": "Bekleyen parçaların seslerini o klasörde ara",
    "Importar do Stream Deck": "Stream Deck’ten içe aktar",
    "Procurar os sons": "Sesleri bul",
    "Escreva o caminho da pasta onde estão os arquivos de som.": "Ses dosyalarının olduğu klasörün yolunu yazın.",
    "Esse arquivo é grande demais (limite: 64 MB). Exporte o backup SEM os áudios embutidos — os sons a gente encontra pela pasta.": "Bu dosya çok büyük (sınır: 64 MB). Yedeği gömülü sesler OLMADAN dışa aktarın — sesleri klasörden buluruz.",
    "🎬 Comandar o OBS (cenas, transição, mudo, live/gravação)": "🎬 OBS’i yönet (sahneler, geçiş, susturma, yayın/kayıt)",
    "Como controlo as cenas do OBS pelo painel?": "OBS sahnelerini panelden nasıl kontrol ederim?",
    "Ligue 🧪 Labs → 🎬 OBS Studio pelo painel (experimental). No OBS, ative Ferramentas → Configurações do Servidor WebSocket e copie a senha para o card do Labs. A ferramenta 🎬 do painel mostra as cenas (no modo estúdio, o clique escolhe o preview e o botão 🎬 manda para o ar), o mudo das fontes e a live/gravação — tudo dentro do seu computador, sem internet.": "🧪 Labs → 🎬 Panelden OBS Studio’yu (deneysel) açın. OBS’te Araçlar → WebSocket Sunucu Ayarları’nı etkinleştirin ve şifreyi Labs kartına kopyalayın. Panelin 🎬 aracı sahneleri (stüdyo modunda tıklama önizlemeyi seçer, 🎬 düğmesi yayına gönderir), kaynak susturmayı ve yayın/kaydı gösterir — hepsi bilgisayarınızın içinde, internetsiz.",
    "O que é a 🎵 Mesa de trilhas?": "🎵 Parça masası nedir?",
    "Uma mesa de som experimental (🧪 Labs): cada trilha vira um botão no painel — e no celular na mesma rede. Uma toca por vez, apertar outra troca com fade, BGM pode repetir (🔁) e o ⏹ para tudo. O som pode sair na live (pelo overlay no OBS), só no painel, ou nos dois. Dá até para importar os botões de som do seu Stream Deck, com um backup de perfis.": "Deneysel bir ses masası (🧪 Labs): her parça panelde bir düğme olur — ve aynı ağdaki telefonda. Aynı anda bir tane çalar, başkasına basmak fade ile değiştirir, BGM tekrarlayabilir (🔁) ve ⏹ her şeyi durdurur. Ses yayına (OBS’teki overlay üzerinden), sadece panele veya ikisine gidebilir. Hatta Stream Deck’inizin ses düğmelerini profil yedeğinden içe aktarabilirsiniz.",
    "🎵 Mesa de trilhas": "🎵 Parça masası",
    "🎬 OBS Studio": "🎬 OBS Studio",
    "Mesa de trilhas (Labs)": "Parça masası (Labs)",
    "Parar a trilha (com fade)": "Parçayı durdur (fade ile)",
    "A mesa está vazia. As trilhas se cadastram em": "Masa boş. Parçalar şurada oluşturulur:",
    "Configurações → 🧪 Labs → 🎵 Mesa de trilhas": "Ayarlar → 🧪 Labs → 🎵 Parça masası",
    "— dá até para importar os botões do seu Stream Deck.": "— hatta Stream Deck düğmelerinizi içe aktarabilirsiniz.",
    "Cada trilha toca onde o destino dela mandar: na live (pelo overlay no OBS), só no painel, ou nos dois. Uma por vez — apertar outra troca com fade.": "Her parça, hedefinin dediği yerde çalar: yayında (OBS’teki overlay üzerinden), sadece panelde veya ikisinde. Aynı anda bir tane — başkasına basmak fade ile değiştirir.",
    "tocando": "çalıyor",
    "(sem nome)": "(adsız)",
    "OBS Studio (Labs)": "OBS Studio (Labs)",
    "A porta e a senha ficam em": "Port ve şifre şurada:",
    "Mandar a cena do preview para o ar (transição de estúdio)": "Önizleme sahnesini yayına gönder (stüdyo geçişi)",
    "Trocar Tela (preview → ao vivo)": "Ekranı Değiştir (önizleme → yayın)",
    "🔊 Fontes de áudio (toque para silenciar)": "🔊 Ses kaynakları (susturmak için dokunun)",
    "Iniciar/encerrar a transmissão (pede confirmação)": "Yayını başlat/bitir (onay ister)",
    "Iniciar/encerrar a gravação (pede confirmação)": "Kaydı başlat/durdur (onay ister)",
    "Iniciar transmissão": "Yayını başlat",
    "Encerrar transmissão": "Yayını bitir",
    "Gravar": "Kaydet",
