    "Cenas (escolhe o preview 👁)": "Sahneler (önizlemeyi seçer 👁)",
    "Cenas (troca direto no ar)": "Sahneler (doğrudan yayında değiştirir)",
    "🟢 conectado": "🟢 bağlı",
    "🟡 procurando o OBS...": "🟡 OBS aranıyor...",
    "📡 AO VIVO": "📡 CANLI",
    "📡 fora do ar": "📡 yayın dışı",
    "⏺ gravando": "⏺ kaydediyor",
    "⏺ parado": "⏺ durdu",
    "Encerrar a TRANSMISSÃO no OBS agora? A live sai do ar.": "OBS’te YAYINI şimdi bitir? Yayın kapanır.",
    "Iniciar a TRANSMISSÃO no OBS agora? Você entra AO VIVO.": "OBS’te YAYINI şimdi başlat? CANLI yayına girersiniz.",
    "Parar a gravação no OBS?": "OBS’te kaydı durdur?",
    "Começar a gravar no OBS?": "OBS’te kayda başla?",
    "Encerrar": "Bitir",
    "🔴 o OBS pede senha — copie a senha em Ferramentas → Configurações do Servidor WebSocket": "🔴 OBS şifre istiyor — Araçlar → WebSocket Sunucu Ayarları’ndan kopyalayın",
    "🔴 senha do OBS errada — confira em Ferramentas → Configurações do Servidor WebSocket": "🔴 OBS şifresi yanlış — Araçlar → WebSocket Sunucu Ayarları’nı kontrol edin",
    "🔴 o OBS fechou a conexão — ele ainda está aberto?": "🔴 OBS bağlantıyı kapattı — hâlâ açık mı?",
    "🔴 o OBS não respondeu — ele está aberto, com o WebSocket ligado?": "🔴 OBS yanıt vermedi — açık mı, WebSocket etkin mi?",

