    "uma vez só, o valor que você quiser": "sadece bir kez, istediğiniz tutarda",
    "🔁 Apoio mensal": "🔁 Aylık destek",
    "renova todo mês, dá para cancelar quando quiser": "her ay yenilenir, istediğiniz zaman iptal edilir",
    "⚡ Amigos do OBS Social": "⚡ OBS Social Dostları",
    "no LivePix · Pix ou cartão": "LivePix’te · Pix veya kart",
    "💜 assinar": "💜 abone ol",
    "Isto é uma assinatura, diferente das doações de cima: ela se repete todo mês até você cancelar (o cancelamento é na sua conta do LivePix, sem falar com ninguém). Nenhum recurso do programa depende disso — tudo continua grátis para todo mundo, sempre.": "Bu bir aboneliktir, yukarıdaki bağışlardan farklı: siz iptal edene kadar her ay tekrarlanır (iptal kendi LivePix hesabınızdan yapılır, kimseyle konuşmanıza gerek yok). Programın hiçbir özelliği buna bağlı değil — her şey herkes için ücretsiz kalır, her zaman.",
    "Aqui fica o ⬅ de voltar quando a pasta está aberta": "Klasör açıkken ⬅ geri tuşu burada durur",
