    "Desligar a câmera virtual do OBS?": "OBS sanal kamerası kapatılsın mı?",
    "Ligar a câmera virtual do OBS?": "OBS sanal kamerası açılsın mı?",
    "não sei o que capturar: o OBS não tem cena no ar": "neyi yakalayacağımı bilmiyorum: OBS’te yayında sahne yok",
    "print vazio ou grande demais": "ekran görüntüsü boş ya da çok büyük",
