    "o replay buffer está desligado — ligue antes de salvar": "tekrar arabelleği kapalı — kaydetmeden önce açın",
    "marcador de capítulo pede OBS 30.2 ou mais novo": "bölüm işareti OBS 30.2 veya daha yenisini ister",
    "o preview só existe com o modo estúdio ligado": "ön izleme yalnızca stüdyo modu açıkken vardır",
    "a transição de estúdio pede o modo estúdio ligado": "stüdyo geçişi stüdyo modunun açık olmasını ister",
    "🎛️ O que aparece no controle do OBS dentro do painel": "🎛️ Paneldeki OBS kontrolünde ne görünsün",
    "Marque só o que você usa. Isso muda a ferramenta 🎬 do painel — as teclas 🎬 da Mesa de Trilhas continuam funcionando de qualquer jeito.": "Sadece kullandıklarınızı işaretleyin. Bu, panelin 🎬 aracını değiştirir — Ses Masası’ndaki 🎬 tuşları her hâlükârda çalışır.",
    "📡 Transmitir, ⏺ gravar, ⏸ pausa, 📷 câmera virtual e ⏪ replay": "📡 Yayın, ⏺ kayıt, ⏸ duraklat, 📷 sanal kamera ve ⏪ tekrar",
