    "👁 Mostrar/esconder as fontes da cena que está no ar": "👁 Yayındaki sahnenin kaynaklarını göster/gizle",
    "🔊 Mixer: mudo e volume de cada fonte de áudio": "🔊 Mikser: her ses kaynağının sessizi ve seviyesi",
    "⏯ Controle de mídia (vídeos e playlists do OBS)": "⏯ Medya kontrolü (OBS videoları ve çalma listeleri)",
