    "🗂 Coleções de cenas e 👤 perfis (troca pesada — vem desligado)": "🗂 Sahne koleksiyonları ve 👤 profiller (ağır değişim — kapalı gelir)",
    "— o controle completo do OBS na ferramenta 🎬 do painel: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela. Tudo isso também vira": "— panelin 🎬 aracında OBS’in tam kontrolü: yayın, kayıt (duraklatma ve bölüm işaretiyle), sanal kamera, tekrar, sahneler, stüdyo modu, geçişler, kaynakları gösterme/gizleme, ses mikseri, medya kontrolü, filtreler, koleksiyonlar, profiller ve ekran görüntüsü. Bunların hepsi ayrıca şuna dönüşür:",
    "botão na Mesa de Trilhas": "Ses Masası’nda düğme",
    "🎬 Comandar o OBS (cenas, live/gravação, mixer, fontes, filtros, mídias — e as teclas 🎬 da Mesa)": "🎬 OBS’i yönet (sahneler, yayın/kayıt, mikser, kaynaklar, filtreler, medya — ve Masa’nın 🎬 tuşları)",
    "Como controlo o OBS pelo painel?": "OBS’i panelden nasıl kontrol ederim?",
    "Ligue 🧪 Labs → 🎬 OBS Studio pelo painel (experimental). Para linkar: no OBS (28+), abra Ferramentas → Configurações do Servidor WebSocket, marque Ativar servidor WebSocket, clique em Mostrar senha das conexões e copie a porta (4455) e a senha para o card do Labs — o passo a passo numerado está lá. Se o OBS estiver em OUTRO computador da rede, ponha o IP dele no campo Endereço (e libere a porta 4455 no firewall daquela máquina). A ferramenta 🎬 do painel comanda tudo: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay buffer, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela — e cada bloco tem um liga/desliga no card do Labs, para a ferramenta ficar do tamanho que você usa. Tudo dentro do seu computador, sem internet.": "🧪 Labs → 🎬 Panelden OBS Studio (deneysel) seçeneğini açın. Bağlamak için: OBS’te (28+) Araçlar → WebSocket Sunucu Ayarları’nı açın, WebSocket sunucusunu etkinleştir’i işaretleyin, Bağlantı Bilgilerini Göster’e tıklayın ve portu (4455) ile parolayı Labs kartına kopyalayın — numaralı adımlar orada. OBS ağdaki BAŞKA bir bilgisayardaysa, onun IP’sini Adres alanına yazın (ve o makinenin güvenlik duvarında 4455 portunu açın). Panelin 🎬 aracı her şeyi yönetir: yayın, kayıt (duraklatma ve bölüm işaretiyle), sanal kamera, tekrar arabelleği, sahneler, stüdyo modu, geçişler, kaynakları gösterme/gizleme, ses mikseri, medya kontrolü, filtreler, koleksiyonlar, profiller ve ekran görüntüsü — ve her bloğun Labs kartında bir açma/kapama düğmesi var, böylece araç tam ihtiyacınız kadar büyük olur. Hepsi bilgisayarınızın içinde, internetsiz.",
    "Dá para transformar as coisas do OBS em botões?": "OBS’teki şeyleri düğmeye dönüştürebilir miyim?",
    "Dá — é a tecla 🎬 Ação do OBS na 🎵 Mesa de trilhas. Crie uma tecla, escolha o tipo 🎬 e depois a ação (trocar de cena, gravar, mudo do microfone, mostrar uma fonte, ligar um filtro, tocar uma mídia...). As listas de cenas, fontes e filtros vêm do OBS conectado; o ▶ Testar agora dispara na hora para você conferir. A tecla acende sozinha quando o que ela controla está ligado (gravando, no ar, fonte visível). Essas teclas também entram dentro de um 🎛️ Botão de multi ação: a fila mistura som e comando — trocar de cena, esperar 2s e tocar a vinheta, por exemplo.": "Dönüştürebilirsiniz — 🎵 Ses Masası’ndaki 🎬 OBS eylemi tuşu bu. Bir tuş oluşturun, 🎬 türünü ve ardından eylemi seçin (sahne değiştirme, kayıt, mikrofonu sessize alma, bir kaynağı gösterme, bir filtreyi açma, bir medya oynatma...). Sahne, kaynak ve filtre listeleri bağlı OBS’ten gelir; ▶ Şimdi dene, kontrol edebilmeniz için eylemi anında tetikler. Kontrol ettiği şey açıkken (kayıt, yayın, kaynak görünür) tuş kendiliğinden yanar. Bu tuşlar bir 🎛️ Çoklu eylem düğmesinin içine de girer: sıra sesi ve komutu karıştırır — örneğin sahneyi değiştir, 2 sn bekle ve jeneriği çal.",
    // ---------- v0.53: rótulos curtos do editor da tecla 🎬 ----------
