    // ---------- v0.54: 🎭 perfis de overlay ----------
    "🎭 Perfis de overlay": "🎭 Overlay profilleri",
    "Um perfil é um": "Bir profil,",
    "molde completo": "eksiksiz bir kalıptır",
    "do comentário em destaque — cores, letra, arte, posição e as peças — guardado com um nome. Monte o visual no card 🎨 acima (e no 🖱️ Organizar a tela), salve como perfil e troque o overlay inteiro em um clique. E com o 🎭 automático, cada comentário destacado veste o molde certo sozinho: um para os comentários comuns e um por": "— öne çıkan yorumun renkleri, yazısı, görseli, konumu ve parçaları — bir adla saklanır. Görünümü yukarıdaki 🎨 kartında (ve 🖱️ Ekranı düzenle içinde) kurun, profil olarak kaydedin ve tüm overlay’i tek tıkla değiştirin. 🎭 otomatik açıkken de öne çıkarılan her yorum doğru kalıbı kendiliğinden giyer: sıradan yorumlar için bir tane ve her",
    "faixa de valor": "değer basamağı",
    "para Super Chats e 💝 doações. A mecânica veio do editor de overlays do": "için bir tane — Super Chat’ler ve 💝 bağışlar için. Bu mekanik şu overlay editöründen geldi:",
