    "Veste o perfil escolhido AGORA no destaque (dá para desfazer no ◀ do card 🎨 e no do Organizar)": "Seçilen profili öne çıkana ŞİMDİ giydirir (🎨 kartının ve Düzenle’nin ◀ tuşuyla geri alınabilir)",
    "✨ Usar este": "✨ Bunu kullan",
    "Grava o visual ATUAL do destaque por cima do perfil escolhido": "Öne çıkanın ŞU ANKİ görünümünü seçilen profilin üzerine yazar",
