    "(o cartão do comentário, com as peças e a arte dele) — widgets, chat fixo e o resto da tela ficam como estão. Para ajustar um perfil: ✨ Usar este → mexa à vontade nos cards e no 🖱️ → 💾 Regravar.": "(yorum kartını, parçaları ve görseliyle) — widget’lar, sabit sohbet ve ekranın kalanı olduğu gibi kalır. Bir profili ayarlamak için: ✨ Bunu kullan → kartları ve 🖱️ istediğiniz gibi kurcalayın → 💾 Üzerine yaz.",
    "Troca automática": "Otomatik geçiş",
    "— cada comentário destacado veste o perfil certo sozinho": "— öne çıkarılan her yorum doğru profili kendiliğinden giyer",
    "Super Chats e 💝 doações vestem o perfil da": "Super Chat’ler ve 💝 bağışlar, değere göre",
    "maior faixa alcançada": "ulaşılan en yüksek basamağın",
    "pelo valor — em qualquer moeda: o programa converte para reais pela cotação do dia. Comentário comum veste o perfil escolhido abaixo. Sem perfil que sirva (ou moeda sem cotação e sem faixa \"a partir de R$ 0\"), fica o visual de sempre.": "profilini giyer — hangi para biriminde olursa olsun: program günün kuruyla real’e çevirir. Sıradan yorum aşağıda seçilen profili giyer. Uyan profil yoksa (ya da kuru olmayan para birimi ve \"R$ 0’dan itibaren\" basamağı yoksa) her zamanki görünüm kalır.",
    "💬 Comentário comum (sem valor) veste": "💬 Sıradan yorum (değersiz) şunu giyer:",
    "— o visual de sempre —": "— her zamanki görünüm —",
    "💰 Faixas por valor (Super Chat e 💝 doação)": "💰 Değere göre basamaklar (Super Chat ve 💝 bağış)",
    "a partir de": "itibaren:",
    "veste": "giyer:",
    "— escolha o perfil —": "— profili seçin —",
    "Coloca no ar um Super Chat de teste com esse valor, para ver o molde vestido de verdade": "Bu değerde bir deneme Super Chat’ini yayına koyar; kalıbı gerçekten giyilmiş görürsünüz",
    "Apagar esta faixa": "Bu basamağı sil",
