    "tanto, use tal perfil. O 🧪 de cada linha coloca no ar um Super Chat de teste com aquele valor, para você ver o molde vestido de verdade (tire do ar antes da live).": "şu kadardan itibaren şu profili kullan. Her satırdaki 🧪, o değerde bir deneme Super Chat’ini yayına koyar; kalıbı gerçekten giyilmiş görürsünüz (yayına girmeden önce onu yayından kaldırın).",
    "O que são os 🎭 Perfis de overlay?": "🎭 Overlay profilleri nedir?",
    "Moldes completos do comentário em destaque — cores, letra, arte, posição e as peças — salvos com um nome, no card 🎭 da aba Aparência. Monte o visual, salve como perfil e troque o overlay inteiro em um clique. Com a": "Öne çıkan yorumun eksiksiz kalıpları — renkler, yazı, görsel, konum ve parçalar — bir adla, Görünüm sekmesindeki 🎭 kartında saklanır. Görünümü kurun, profil olarak kaydedin ve tüm overlay’i tek tıkla değiştirin. ",
    "troca automática": "Otomatik geçiş",
    "ligada, cada comentário destacado veste o molde certo sozinho: um perfil para os comentários comuns e um por": "açıkken öne çıkarılan her yorum doğru kalıbı kendiliğinden giyer: sıradan yorumlar için bir profil ve her biri için bir tane —",
    "Tamanho do comentário de exemplo, em letras — para testar se um comentário comprido cabe no seu overlay (muda no ar na hora)": "Örnek yorumun boyutu, harf olarak — uzun bir yorumun overlay’inize sığıp sığmadığını denemek için (yayında anında değişir)",
    "✍️ letras": "✍️ harf",
