    "— nenhum perfil salvo ainda —": "— henüz kayıtlı profil yok —",
    "Nenhuma faixa ainda — crie com ➕ ou use as 🪜 clássicas.": "Henüz basamak yok — ➕ ile oluşturun ya da 🪜 klasikleri kullanın.",
    "Perfis de overlay": "Overlay profilleri",
