    // ---------- v0.55: 🖼️ Suas artes + modo edição de molde ----------
    "🖼️ Suas artes — imagens e vídeos nos overlays": "🖼️ Görselleriniz — overlay’lerde resimler ve videolar",
    "Envie qualquer imagem ou vídeo e escolha": "Herhangi bir resim veya video yükleyin ve seçin:",
    ", logo acima. E com um molde em edição no 🖱️, escolher o": ", hemen yukarıda. Ve 🖱️ içinde düzenlenen bir kalıp varken,",
