    "dentro do Destaque no 🖱️ — dá para arrastar, esticar, girar e escolher o encaixe, como qualquer outra peça. Para a arte virar o cartão inteiro, ligue": "🖱️ içindeki Öne çıkanın içinde — sürükleyin, esnetin, döndürün ve yerleşimi seçin, diğer parçalar gibi. Görselin kartın tamamı olması için de şunu açın:",
    "🎭 Editando": "🎭 Düzenlenen",
    "— Visual ao vivo —": "— Canlı görünüm —",
