    "na 🎵 Mesa de trilhas. Crie uma tecla, escolha o tipo 🎬 e depois a ação (trocar de cena, gravar, mudo do microfone, mostrar uma fonte, ligar um filtro, tocar uma mídia...). As listas de cenas, fontes e filtros vêm do OBS conectado; o ▶ Testar agora dispara na hora para você conferir. A tecla": "🎵 Ses masasında. Bir tuş oluşturun, 🎬 türünü ve sonra eylemi seçin (sahne değiştir, kaydet, mikrofonu sustur, bir kaynağı göster, bir filtreyi aç, bir medya çal...). Sahne, kaynak ve filtre listeleri bağlı OBS’den gelir; ▶ Şimdi dene anında tetikler. Tuş,",
    "acende sozinha": "kendiliğinden yanar",
    "quando o que ela controla está ligado (gravando, no ar, fonte visível). Essas teclas também entram dentro de um 🎛️ Botão de multi ação: a fila mistura som e comando — trocar de cena, esperar 2s e tocar a vinheta, por exemplo.": "kontrol ettiği şey açıkken (kayıtta, yayında, kaynak görünür). Bu tuşlar 🎛️ Çoklu eylem düğmesine de girer: kuyruk ses ve komutu karıştırır — sahne değiştir, 2 sn bekle ve cıngılı çal, mesela.",
    "🎨 Temas → 🖼️ Suas artes": "🎨 Temalar → 🖼️ Görselleriniz",
    ", na aba Aparência).": ", Görünüm sekmesinde).",
    "⚠️ Você está EDITANDO um molde no 🖱️ — volte para «— Visual ao vivo —» antes de vestir um perfil na live.": "⚠️ 🖱️ içinde bir kalıp DÜZENLİYORSUNUZ — yayına bir profil giydirmeden önce «— Canlı görünüm —»e dönün.",
    "Escolha um som primeiro (envie o arquivo em 🎨 Temas → 🖼️ Suas artes).": "Önce bir ses seçin (dosyayı 🎨 Temalar → 🖼️ Görselleriniz’e yükleyin).",
