    "🎯 Faixas — por 💰 valor, 🎨 cor do Super Chat ou 🔤 palavra no nome": "🎯 Basamaklar — 💰 tutara, 🎨 Super Chat rengine veya 🔤 addaki kelimeye göre",
    "Cada faixa escolhe COMO casar: 💰 a partir de um valor em reais (Super Chat e 💝 doação, qualquer moeda); 🎨 pelo tom que o próprio YouTube pintou no Super Chat; ou 🔤 por uma palavra que aparece no espaço do nome (o nome, «Membro», o nível do canal...). Quando mais de uma serve, a ordem é: cor → valor → palavra → comentário comum.": "Her basamak NASIL eşleşeceğini seçer: 💰 real cinsinden bir tutardan itibaren (Super Chat ve 💝 bağış, her para birimi); 🎨 YouTube’un Super Chat’e boyadığı tona göre; veya 🔤 ad alanında görünen bir kelimeye göre (ad, «Üye», kanal seviyesi...). Birden fazlası uyarsa sıra: renk → tutar → kelime → sıradan yorum.",
