    "Centralizar na tela (leva esta peça para o meio do canvas)": "Ekranda ortala (bu parçayı tuvalin ortasına taşır)",
    "Na live, este comentário vestiria o molde": "Canlı yayında bu yorum şu şablonu giyerdi",
    "A prévia mostra o visual ao vivo, que é o que você está editando — para ajustar o molde, abra-o no seletor 🎭 Editando.": "Önizleme, düzenlemekte olduğunuz canlı görünümü gösterir — şablonu ayarlamak için onu 🎭 Düzenleniyor seçicisinde açın.",
    "Clique num overlay ou numa peça para ver e digitar as medidas dele.": "Ölçülerini görmek ve yazmak için bir overlay’e veya parçaya tıklayın.",
    "🧩 Clique numa peça do mapa para ajustá-la aqui (tamanho, caixa, giro, opacidade, cor...).": "🧩 Burada ayarlamak için haritadaki bir parçaya tıklayın (boyut, kutu, döndürme, opaklık, renk...).",
