    "Camada": "Katman",
    "— escolha um perfil —": "— bir profil seçin —",
    "Há mudanças não salvas. Trocar de perfil e descartá-las?": "Kaydedilmemiş değişiklikler var. Profil değiştirilsin ve bunlar atılsın mı?",
    "Descartar as mudanças não salvas e recarregar o perfil?": "Kaydedilmemiş değişiklikler atılsın ve profil yeniden yüklensin mi?",
