    "dele (quem fica por cima — vale na live de verdade). O 👁 esconde só aqui no editor; o 🔒 trava contra esbarrões.": "değiştirir (kim üstte kalır — gerçek yayında geçerli). 👁 yalnız burada, düzenleyicide gizler; 🔒 yanlışlıkla çarpmalara karşı kilitler.",
    "🎭 Troca automática — cada comentário destacado veste o perfil certo sozinho": "🎭 Otomatik değişim — öne çıkan her yorum doğru profili kendiliğinden giyer",
    "Ligar a troca automática": "Otomatik değişimi aç",
    "— um seletor para cada overlay/widget. Para moldura de tela inteira, crie em 1920×1080 com fundo transparente (PNG ou WebM). O fundo do comentário em destaque se escolhe lá em cima, na linha": "— overlay/widget başına bir seçici. Tam ekran çerçeve için 1920×1080, şeffaf arka planlı (PNG veya WebM) oluşturun. Öne çıkan yorumun arka planı yukarıda,",
    "— e com um molde em edição, a arte escolhida grava DENTRO do perfil.": "satırında seçilir — ve düzenlenen bir kalıp varken seçilen görsel profilin İÇİNE kaydedilir.",
    "Veste o perfil escolhido AGORA no visual ao vivo do destaque (dá para desfazer no ◀)": "Öne çıkanın canlı görünümüne seçilen profili ŞİMDİ giydirir (◀ ile geri alınır)",
