    "↩️ Descartar mudanças": "↩️ Değişiklikleri at",
    "↺ Destaque padrão": "↺ Standart öne çıkan",
    "Joga fora o que você mexeu neste molde e volta à última foto dele (de quando você entrou, ou do último 💾)": "Bu kalıpta değiştirdiklerinizi atar ve son fotoğrafına döner (girdiğiniz andan, ya da son 💾’den)",
    "O comentário em destaque volta ao padrão do programa: sem arte, montagem normal, posição e tamanho de sempre (os perfis salvos não mudam)": "Öne çıkan yorum programın standardına döner: görselsiz, normal montaj, her zamanki konum ve boyut (kayıtlı profiller değişmez)",
    "Jogar fora o que você mexeu neste molde e voltar à última foto dele (de quando você entrou, ou do último 💾)?": "Bu kalıpta değiştirdiklerinizi atıp son fotoğrafına dönülsün mü (girdiğiniz andan, ya da son 💾’den)?",
    "O comentário em destaque volta ao PADRÃO do programa: sem arte, montagem normal, posição e tamanho de sempre. Os perfis salvos não mudam. (Dá para desfazer no ◀ do Organizar.)": "Öne çıkan yorum programın STANDARDINA döner: görselsiz, normal montaj, her zamanki konum ve boyut. Kayıtlı profiller değişmez. (Düzenle’nin ◀’ü ile geri alınır.)",
    "Descartar": "At",
