    // ---------- v0.59: textos sem comparações ----------
    "A sua tela (16:9) inteira como mesa de trabalho.": "Bütün (16:9) ekranınız çalışma tezgâhı olarak.",
    "da tela 1920×1080.": "1920×1080 ekranın.",
    "— junto dos 🎭 Perfis de overlay: envie a imagem ou o vídeo e escolha onde ela entra (fundo do destaque, moldura de tela inteira ou fundo de widget). Com uma arte no fundo do destaque, o overlay padrão sai de cena sozinho: a arte vira a peça 🖼️ Sua arte no Organizar a tela, com posição e tamanho ajustáveis — e, com um molde em edição no 🖱️, a arte escolhida grava dentro do perfil.": "— 🎭 Overlay profillerinin yanında: resmi veya videoyu yükleyin ve nereye gireceğini seçin (öne çıkan arka planı, tam ekran çerçeve veya widget arka planı). Öne çıkanın arka planında bir görsel varken standart overlay sahneden kendiliğinden çekilir: görsel, Ekranı düzenle’de 🖼️ Görseliniz parçasına dönüşür; konumu ve boyutu ayarlanabilir — ve 🖱️ içinde düzenlenen bir kalıp varken seçilen görsel profilin içine kaydedilir.",
    "para Super Chats e 💝 doações — em qualquer moeda, convertida para reais pela cotação do dia. O 🧪 de cada faixa põe no ar um Super Chat de teste com aquele valor, para conferir antes da live.": "Super Chat’ler ve 💝 bağışlar için — her para biriminde, günün kuruyla reale çevrilir. Her basamağın 🧪’ü o tutarla bir deneme Super Chat’ini yayına koyar; yayından önce kontrol edersiniz.",
    "— colaborador de vários elementos para o OBS Social.": "— OBS Social için birçok öğenin katkıcısı.",
    "📺 Rede do overlay": "📺 Overlay ağı",
    "🌐 Compartilhado (todas)": "🌐 Paylaşımlı (hepsi)",
    "▶️ Só YouTube": "▶️ Yalnız YouTube",
    "💜 Só Twitch": "💜 Yalnız Twitch",
    "🟢 Só Kick": "🟢 Yalnız Kick",
    "💙 Só Bilibili": "💙 Yalnız Bilibili",
    "Este visual/molde é de qual rede? O 🎭 automático só veste o molde em comentários da rede escolhida — compartilhado serve para todas": "Bu görsel/şablon hangi ağ için? 🎭 otomatik mod, şablonu yalnızca seçilen ağın yorumlarına giydirir — paylaşımlı hepsinde geçerlidir",
    "💠 Pix direto do banco (experimental)": "💠 Doğrudan bankadan Pix (deneysel)",
    "— cada Pix recebido na sua conta vira um apoio na aba 💝 Apoios do painel, com a mensagem que a pessoa escreveu no app do banco": "— hesabınıza gelen her Pix, kişinin banka uygulamasında yazdığı mesajla birlikte panelin 💝 Destekler sekmesinde bir destek olur",
    "Sem intermediário e sem taxa de plataforma: o programa consulta a": "Aracı yok, platform ücreti yok: program",
    "API Pix do SEU banco": "KENDİ bankanızın Pix API’sini",
    "(padrão do Banco Central) de tempos em tempos. Você precisa criar um aplicativo no portal do desenvolvedor do banco e colar aqui as credenciais e o certificado que ele fornecer. Perfis prontos:": "(Merkez Bankası standardı) ara ara sorgular. Bankanın geliştirici portalında bir uygulama oluşturup verdiği kimlik bilgilerini ve sertifikayı buraya yapıştırmalısınız. Hazır profiller:",
    "(conta PJ — MEI serve; certificado sai de graça no portal) e": "(işletme hesabı — MEI olur; sertifika portalda ücretsiz) ve",
    "(PJ e": "(işletme ve",
    "pessoa física": "bireysel",
    "; usa certificado ICP-Brasil no CPF/CNPJ). Outro banco que siga o padrão? Use o perfil personalizado.": "; CPF/CNPJ üzerinde ICP-Brasil sertifikası kullanır). Standarda uyan başka bir banka mı? Özel profili kullanın.",
    "Banco": "Banka",
    "Consultar a cada (segundos)": "Sorgu aralığı (saniye)",
    "Client ID (do portal do banco)": "Client ID (banka portalından)",
