    "Senha do certificado (só para .pfx)": "Sertifika parolası (yalnız .pfx)",
    "URL do token (OAuth do banco)": "Token URL’si (bankanın OAuth’u)",
    "URL da consulta de Pix (GET /pix)": "Pix sorgu URL’si (GET /pix)",
    "Escopo OAuth": "OAuth kapsamı",
    "Personalizado (outro banco)": "Özel (başka banka)",
    "🧪 Pix de exemplo": "🧪 Örnek Pix",
    "Salvar e conectar ao banco": "Kaydet ve bankaya bağlan",
    "Manda um apoio Pix de mentira para o painel — para ver a aba Apoios e o visual na tela sem depender do banco": "Panele sahte bir Pix desteği gönderir — bankaya bağımlı olmadan Destekler sekmesini ve ekran görünümünü görmek için",
    "As credenciais e a senha ficam guardadas só neste computador (na pasta": "Kimlik bilgileri ve parola yalnızca bu bilgisayarda saklanır (",
    ") e nunca são enviadas às telas. A primeira consulta boa apenas reconhece os Pix que já existiam — só os que chegarem DEPOIS viram apoio no painel. A mensagem do pagador é garantida nos Pix pagos por QR de cobrança; na transferência manual para a chave, depende do banco.": " klasöründe) ve asla ekranlara gönderilmez. İlk başarılı sorgu yalnızca zaten var olan Pix’leri tanır — yalnızca SONRA gelenler panelde destek olur. Ödeyenin mesajı, tahsilat QR’ı ile ödenen Pix’lerde garantidir; anahtara elle havalede bankaya bağlıdır.",
    "desligado (ligue o seletor acima)": "kapalı (yukarıdaki anahtarı açın)",
    "conectado ao banco — consultando os Pix recebidos": "bankaya bağlı — gelen Pix’ler sorgulanıyor",
    "conectando ao banco...": "bankaya bağlanılıyor...",
    "erro": "hata",
    "•••• (guardado — em branco = manter)": "•••• (kayıtlı — boş = koru)",
    "em branco = não mexer no guardado": "boş = kayıtlıya dokunma",
    "Nenhum comentário na tela. Clique com o": "Ekranda yorum yok. Bir yoruma",
    "em um comentário e escolha «📺 Enviar para a tela».": "yapıp «📺 Ekrana gönder»i seçin.",
    "No painel, clique com o botão direito no comentário e escolha «📺 Enviar para a tela». Ele aparece no overlay na hora — e sai quando você tirar (ou sozinho, se você definir o ⏱️ tempo de tela). O clique simples não envia nada: é uma proteção contra o clique acidental no meio da live.": "Panelde yoruma sağ tıklayıp «📺 Ekrana gönder»i seçin. Overlay’de anında görünür — kaldırınca gider (⏱️ ekran süresi tanımlarsanız kendiliğinden de). Tek tıklama hiçbir şey göndermez: yayın ortasında yanlışlıkla tıklamaya karşı korumadır.",
    "100% oficial e grátis, pela Bot API: crie um bot no": "Bot API ile %100 resmi ve ücretsiz:",
    "(dentro do Telegram), coloque o bot no": "(Telegram içinde) bir bot oluşturun, botu",
