    "e cole aqui o token e o grupo. Para o ⏳ timeout e o 🚫 banimento valerem no próprio grupo, faça o bot": "ekleyin ve token ile grubu buraya yapıştırın. ⏳ zaman aşımı ve 🚫 yasağın grubun kendisinde de geçerli olması için botu",
