    "do grupo.": ".",
    "token do bot (do @BotFather)": "bot token’ı (@BotFather’dan)",
    "grupo: @nomedogrupo ou id (vazio = qualquer conversa do bot)": "grup: @grupadı veya id (boş = botun tüm sohbetleri)",
    "🛡️ Timeout e banimento (Telegram e WhatsApp)": "🛡️ Zaman aşımı ve yasak (Telegram ve WhatsApp)",
    "Quem foi colocado de castigo pelo painel (botão direito no comentário) aparece aqui. O castigo vale SEMPRE dentro do OBS Social — mensagens da pessoa nem entram no painel — e, no Telegram, também é aplicado no próprio grupo quando o bot é admin. Timeouts vencidos saem da lista sozinhos.": "Panelden (yoruma sağ tık) cezalandırılanlar burada görünür. Ceza OBS Social içinde HER ZAMAN geçerlidir — kişinin mesajları panele bile girmez — ve Telegram’da bot yöneticiyse grubun kendisinde de uygulanır. Süresi dolan zaman aşımları listeden kendiliğinden çıkar.",
    "⏳ Timeouts — Telegram": "⏳ Zaman aşımları — Telegram",
    "🚫 Banimentos — Telegram": "🚫 Yasaklar — Telegram",
    "⏳ Timeouts — WhatsApp": "⏳ Zaman aşımları — WhatsApp",
    "🚫 Banimentos — WhatsApp": "🚫 Yasaklar — WhatsApp",
    "Ninguém de castigo aqui. 🎉": "Burada cezalı kimse yok. 🎉",
    "✔ Liberar": "✔ Serbest bırak",
    "📨 Telegram (experimental)": "📨 Telegram (deneysel)",
    "— os inscritos comentam no grupo da live e tudo cai numa coluna própria do painel: texto, foto, áudio, vídeo e documento, com prévia antes de ir para a tela, resposta com assinatura e ⏳ timeout / 🚫 banimento direto da coluna": "— aboneler yayın grubunda yorum yapar ve her şey panelin kendi sütununa düşer: metin, fotoğraf, ses, video ve belge; ekrana çıkmadan önizleme, imzalı yanıt ve sütundan doğrudan ⏳ zaman aşımı / 🚫 yasak",
    "Usa a": "Kullanılan:",
    "Bot API oficial e gratuita": "Telegram’ın resmî ve ücretsiz Bot API’si",
    "do Telegram — sem risco e sem mensalidade. Ligue aqui e configure o bot em 🔌 Conexões. A mídia dos inscritos fica em quarentena na pasta": "— risk yok, aylık ücret yok. Buradan açın ve botu 🔌 Bağlantılar’da kurun. Abone medyası",
    "e SÓ aparece na tela quando você mandar (botão direito → 📺). Nomes que parecem telefone continuam mascarados na tela, como sempre.": "klasöründe karantinada kalır ve SADECE siz gönderince (sağ tık → 📺) ekranda görünür. Telefona benzeyen adlar her zamanki gibi ekranda maskeli kalır.",
    "📺 Enviar para a tela": "📺 Ekrana gönder",
