    "(dentro do Telegram) e cole aqui o token. As pessoas podem falar": "(Telegram içinde) oluşturun ve token’ı buraya yapıştırın. İnsanlar",
    "direto com o bot": "botla doğrudan konuşabilir",
    "(chat privado) — não precisa de grupo. Quer usar um grupo da live também? Coloque o bot nele e preencha o campo do grupo (o privado continua entrando). Para o ⏳ timeout e o 🚫 banimento valerem dentro do grupo, faça o bot": "(özel sohbet) — grup gerekmez. Yayın grubu da mı istiyorsunuz? Botu gruba ekleyip grup alanını doldurun (özel sohbetler gelmeye devam eder). ⏳ zaman aşımı ve 🚫 yasağın grup içinde geçerli olması için botu",
    "; no privado, o castigo vale pelo filtro do próprio OBS Social.": "; özelde ceza OBS Social’ın kendi filtresiyle geçerlidir.",
    "— as pessoas falam direto com o bot (chat privado) e/ou num grupo da live, e tudo cai numa coluna própria do painel: texto, foto, áudio, vídeo e documento, com prévia antes de ir para a tela, resposta com assinatura e ⏳ timeout / 🚫 banimento direto da coluna": "— insanlar botla doğrudan (özel sohbet) ve/veya yayın grubunda konuşur, her şey panelin kendi sütununa düşer: metin, fotoğraf, ses, video ve belge; ekrana çıkmadan önizleme, imzalı yanıt ve sütundan doğrudan ⏳ zaman aşımı / 🚫 yasak",
    "opcional — grupo: @nomedogrupo ou id (vazio = privados e qualquer grupo do bot)": "isteğe bağlı — grup: @grupadı veya id (boş = özel sohbetler ve botun tüm grupları)",
    "📨 Telegram entra no sorteio": "📨 Telegram çekilişe katılır",
    "💬 WhatsApp entra no sorteio": "💬 WhatsApp çekilişe katılır",
    "fichas por pessoa do Telegram": "Telegram’daki kişi başına bilet",
    "fichas por pessoa do WhatsApp": "WhatsApp’taki kişi başına bilet",
    "Redes de mensagem entram": "Mesajlaşma ağları varsayılan olarak",
    "desligadas por padrão": "kapalıdır",
    ": ligue aqui se quiser que elas concorram. Como não existem níveis de sub/membro nelas, você define quantas fichas cada pessoa vale (no sorteio aberto todo mundo vale 1).": ": yarışmalarını istiyorsanız buradan açın. Orada abone/üye seviyeleri olmadığından her kişinin kaç bilet edeceğine siz karar verirsiniz (açık çekilişte herkes 1 eder).",
    "Desligado (padrão): quem fala pelo Telegram NÃO entra no sorteio. Ligado: cada pessoa do Telegram entra com as fichas definidas abaixo.": "Kapalı (varsayılan): Telegram’dan konuşanlar çekilişe KATILMAZ. Açık: Telegram’daki her kişi aşağıda belirlenen biletlerle katılır.",
    "Desligado (padrão): quem fala pelo WhatsApp NÃO entra no sorteio. Ligado: cada pessoa do WhatsApp entra com as fichas definidas abaixo.": "Kapalı (varsayılan): WhatsApp’tan konuşanlar çekilişe KATILMAZ. Açık: WhatsApp’taki her kişi aşağıda belirlenen biletlerle katılır.",
    "Fichas de cada participante do Telegram (1 a 100) — como não existem níveis por lá, quem define é você": "Telegram’daki her katılımcının bileti (1–100) — orada seviye olmadığından siz belirlersiniz",
    "Fichas de cada participante do WhatsApp (1 a 100) — como não existem níveis por lá, quem define é você": "WhatsApp’taki her katılımcının bileti (1–100) — orada seviye olmadığından siz belirlersiniz",
    "🎙️ Transcrição local (experimental)": "🎙️ Yerel transkripsiyon (deneysel)",
    "— os áudios e vídeos que os inscritos mandam ganham um rascunho de texto no cartão do painel, transcrito no seu computador": "— abonelerin gönderdiği ses ve videolara, bilgisayarınızda çözümlenen bir metin taslağı panel kartında eklenir",
    "Nada vai para a nuvem: a transcrição roda na sua máquina com o": "Hiçbir şey buluta gitmez: transkripsiyon makinenizde",
    "(o motor aberto do Whisper, de graça). O motor e os modelos são": "(Whisper’ın açık motoru, ücretsiz) ile çalışır. Motor ve modeller",
    "baixados sob demanda": "istek üzerine indirilir",
    "em 🔌 Conexões — nada vem embutido no programa. A fila processa um arquivo por vez, para não pesar na live.": "(🔌 Bağlantılar’dan) — programla birlikte hiçbir şey gelmez. Kuyruk, yayını yormamak için dosyaları tek tek işler.",
    "🎙️ Transcrição local (Labs)": "🎙️ Yerel transkripsiyon (Labs)",
    "Cada áudio/vídeo recebido dos inscritos vira um": "Abonelerden gelen her ses/video bir",
    "rascunho de texto": "metin taslağına dönüşür",
    "no cartão do painel — transcrito no seu computador, nada sai dele. Escolha o modelo, baixe o que for usar e pronto. Quanto maior o modelo, mais precisa (e mais pesada) a transcrição. Baixar/apagar modelos e trocar o comando só funciona no computador onde o OBS Social roda.": "— bilgisayarınızda çözümlenir, hiçbir şey dışarı çıkmaz. Modeli seçin, kullanacağınızı indirin, bitti. Model ne kadar büyükse transkripsiyon o kadar isabetli (ve ağır) olur. Model indirme/silme ve komut değiştirme yalnızca OBS Social’ın çalıştığı bilgisayarda yapılabilir.",
    "Modelo em uso": "Kullanılan model",
    "🐜 Tiny — o mais leve e rápido (menos preciso)": "🐜 Tiny — en hafif ve hızlı (daha az isabetli)",
    "🐇 Base — leve e razoável (bom começo)": "🐇 Base — hafif ve makul (iyi başlangıç)",
    "🐕 Small — bom equilíbrio": "🐕 Small — iyi denge",
    "🐎 Medium — bem preciso (pede máquina boa)": "🐎 Medium — oldukça isabetli (iyi makine ister)",
    "🐘 Large v3 Turbo — o mais preciso": "🐘 Large v3 Turbo — en isabetli",
