    "⚠️ o motor de transcrição ainda não está pronto (Configurações → Conexões) — clique para tentar de novo": "⚠️ transkripsiyon motoru henüz hazır değil (Ayarlar → Bağlantılar) — yeniden denemek için tıklayın",
    "⚠️ este formato precisa do conversor ffmpeg (Configurações → Conexões) — clique para tentar de novo": "⚠️ bu format ffmpeg dönüştürücüsünü ister (Ayarlar → Bağlantılar) — yeniden denemek için tıklayın",
    "⚠️ a conversão do áudio falhou — clique para tentar de novo": "⚠️ ses dönüştürme başarısız — yeniden denemek için tıklayın",
    "⚠️ o motor de transcrição falhou neste arquivo — clique para tentar de novo": "⚠️ transkripsiyon motoru bu dosyada başarısız oldu — yeniden denemek için tıklayın",
