    "💬 WhatsApp (experimental)": "💬 WhatsApp (deneysel)",
    "— as pessoas falam direto com o número da live (e/ou num grupo), e tudo cai numa coluna própria do painel: texto, foto, áudio, vídeo e documento, com prévia, transcrição, resposta assinada e ⏳ timeout / 🚫 banimento direto da coluna": "— insanlar yayın numarasıyla doğrudan (ve/veya bir grupta) konuşur, her şey panelin kendi sütununa düşer: metin, fotoğraf, ses, video ve belge; önizleme, transkripsiyon, imzalı yanıt ve sütundan doğrudan ⏳ zaman aşımı / 🚫 yasak",
    "Leia antes de ligar:": "Açmadan önce okuyun:",
    "este conector usa o gateway": "bu bağlayıcı",
    "(pago), que NÃO é oficial da Meta — é engenharia reversa do protocolo, e existe": "geçidini (ücretli) kullanır; Meta’nın resmî ürünü DEĞİLDİR — protokolün tersine mühendisliğidir ve",
    "risco real de banimento do número": "numaranın yasaklanması gerçek bir risktir",
    "usado. Use um": ".",
    "número SECUNDÁRIO dedicado à live": "yayına özel İKİNCİL bir numara kullanın",
    ", nunca o seu pessoal. Ligue aqui e configure o token em 🔌 Conexões. A mídia dos inscritos fica em quarentena na pasta": ", asla kişisel numaranızı değil. Burada açın ve token’ı 🔌 Bağlantılar’da ayarlayın. Abone medyası",
    "e só vai para a tela quando você mandar (botão direito → 📺); nomes que parecem telefone continuam mascarados na tela, como sempre. Uma opção por biblioteca aberta rodando no seu computador (sem gateway e sem mensalidade — mesmo risco) está a caminho.": "klasöründe karantinada kalır ve yalnızca siz gönderince ekrana çıkar (sağ tık → 📺); telefona benzeyen adlar ekranda her zamanki gibi maskelenir. Bilgisayarınızda çalışan açık kütüphane seçeneği (geçitsiz ve aboneliksiz — aynı risk) yolda.",
    "(pago, NÃO oficial da Meta): crie um canal no painel do Whapi, escaneie o QR com o": "geçidi üzerinden (ücretli, Meta resmî DEĞİL): Whapi panelinde bir kanal oluşturun, QR’ı",
    "número da live": "yayın numarasıyla",
    "e cole aqui o token do canal. ⚠️ Por não ser oficial, existe": "tarayın ve kanal token’ını buraya yapıştırın. ⚠️ Resmî olmadığından",
    "— use um número SECUNDÁRIO dedicado à live, nunca o pessoal. Conversas diretas com o número entram sempre; quer um grupo também? Preencha o campo do grupo. O ⏳ timeout vale pelo filtro do próprio OBS Social; o 🚫 banimento também bloqueia o número da pessoa no gateway.": "— yayına özel İKİNCİL bir numara kullanın, asla kişisel numaranızı değil. Numarayla doğrudan sohbetler her zaman girer; grup da mı istiyorsunuz? Grup alanını doldurun. ⏳ zaman aşımı OBS Social’ın kendi filtresiyle geçerli; 🚫 yasak kişinin numarasını geçitte de engeller.",
    "token do canal (do painel do Whapi)": "kanal token’ı (Whapi panelinden)",
    "opcional — grupo: id (…@g.us) ou nome exato (vazio = diretas e qualquer grupo)": "isteğe bağlı — grup: id (…@g.us) veya tam ad (boş = doğrudan sohbetler ve tüm gruplar)",
    "Via gateway": "Geçit:",
    "🌐 Gateway Whapi (pago — cole o token do canal)": "🌐 Whapi geçidi (ücretli — kanal token’ını yapıştırın)",
    "🖥️ Biblioteca local (grátis — QR no seu computador, sem gateway)": "🖥️ Yerel kütüphane (ücretsiz — bilgisayarınızda QR, geçitsiz)",
    "As duas formas usam o mesmo protocolo não oficial — o risco de banimento é igual; muda quem faz a ponte": "İki yol da aynı resmî olmayan protokolü kullanır — yasak riski aynıdır; değişen tek şey köprüyü kimin kurduğudur",
    "A biblioteca aberta (": "Açık kütüphane (",
    ") roda 100% no seu computador — sem gateway e sem mensalidade, com o": ") bilgisayarınızda %100 çalışır — geçitsiz ve aboneliksiz,",
    "mesmo risco": "aynı riskle",
    "de banimento (número SECUNDÁRIO sempre). Baixe a biblioteca uma vez, conecte e escaneie o QR que aparece aqui com o WhatsApp do número da live (Configurações → Aparelhos conectados). A sessão fica guardada e sobrevive a reinícios.": "yasaklanma (her zaman İKİNCİL numara). Kütüphaneyi bir kez indirin, bağlanın ve burada çıkan QR’ı yayın numarasının WhatsApp’ıyla tarayın (Ayarlar → Bağlı cihazlar). Oturum kaydedilir ve yeniden başlatmalarda kalır.",
    "Baixar a biblioteca local agora (via npm, sob demanda)": "Yerel kütüphaneyi şimdi indir (npm ile, istek üzerine)",
    "Apagar a sessão pareada — para trocar de número ou recomeçar o pareamento": "Eşleştirilmiş oturumu sil — numara değiştirmek veya eşleştirmeye baştan başlamak için",
    "Apagar a sessão pareada (trocar de número)": "Eşleştirilmiş oturumu sil (numara değiştir)",
    "📱 Escaneie com o WhatsApp do número da live: Configurações → Aparelhos conectados → Conectar aparelho.": "📱 Yayın numarasının WhatsApp’ıyla tarayın: Ayarlar → Bağlı cihazlar → Cihaz bağla.",
    "baixando a biblioteca... (pode levar um minuto)": "kütüphane indiriliyor... (bir dakika sürebilir)",
    "✔ biblioteca instalada — conecte e escaneie o QR": "✔ kütüphane kuruldu — bağlanın ve QR’ı tarayın",
    "a biblioteca ainda não foi baixada — clique em ⬇️": "kütüphane henüz indirilmedi — ⬇️ tıklayın",
    "Apagar a sessão pareada do WhatsApp? Você vai precisar escanear o QR de novo.": "Eşleştirilmiş WhatsApp oturumu silinsin mi? QR’ı yeniden taramanız gerekecek.",
    "e só vai para a tela quando você mandar (botão direito → 📺); nomes que parecem telefone continuam mascarados na tela, como sempre. Dá para escolher entre DOIS modos no card de Conexões: o gateway Whapi (pago) ou a biblioteca aberta rodando no seu computador (grátis, QR — mesmo risco).": "klasöründe karantinada kalır ve yalnızca siz gönderince ekrana çıkar (sağ tık → 📺); telefona benzeyen adlar ekranda her zamanki gibi maskelenir. Bağlantılar kartında İKİ mod seçebilirsiniz: Whapi geçidi (ücretli) veya bilgisayarınızda çalışan açık kütüphane (ücretsiz, QR — aynı risk).",
