    "Se o ⏳ Timer estiver combinado com os Avisos, o recado também sai sozinho quando o tempo acabar.": "⏳ Zamanlayıcı Duyurularla eşleştirilmişse, süre bitince mesaj da kendiliğinden çıkar.",
