    "⚙️ Ligado, a configuração completa mora na página «🎬 OBS Studio Remoto» do menu à esquerda (logo depois de 🎨 Temas).": "⚙️ Açıkken tüm yapılandırma sol menüdeki «🎬 Uzaktan OBS Studio» sayfasında yaşar (🎨 Temalar’dan hemen sonra).",
    "⚙️ Ligada, a configuração completa mora na página «🎵 Mesa de Trilhas» do menu à esquerda (logo depois de 🎨 Temas).": "⚙️ Açıkken tüm yapılandırma sol menüdeki «🎵 Parça Masası» sayfasında yaşar (🎨 Temalar’dan hemen sonra).",
    "A porta e a senha ficam na página «🎬 OBS Studio Remoto» das configurações.": "Port ve şifre, ayarların «🎬 Uzaktan OBS Studio» sayfasında yaşar.",
