    "Qualquer coisa com atalho no OBS (até de plugin) dispara daqui — é o coringa do que ainda não tem botão próprio.": "OBS’de kısayolu olan her şey (eklentilerden bile) buradan tetiklenir — henüz özel düğmesi olmayanların jokeri.",
