    "📊 Saúde do OBS: fps, CPU, memória, disco, quadros perdidos e tempos de transmissão/gravação": "📊 OBS sağlığı: fps, CPU, bellek, disk, kayıp kareler ve yayın/kayıt süreleri",
    "⌨️ Disparar atalhos do OBS por nome — o coringa do que não tem botão próprio (vem desligado)": "⌨️ OBS kısayollarını adla tetikle — özel düğmesi olmayanların jokeri (varsayılan kapalı)",
    "🎬 Criar teclas do OBS na Mesa (escolha o que quiser)": "🎬 Masada OBS tuşları oluştur (istediğinizi seçin)",
    "Marque os recursos do seu OBS e aperte ➕: cada um vira uma tecla DE VERDADE na Mesa — dá para mover, renomear, colorir e apagar como qualquer outra. Depois de criar, é só arrastar cada tecla para a célula que quiser.": "OBS kaynaklarınızı işaretleyip ➕ basın: her biri ses masasında GERÇEK bir tuş olur — diğerleri gibi taşıyabilir, yeniden adlandırabilir, renklendirebilir ve silebilirsiniz. Oluşturduktan sonra her tuşu istediğiniz hücreye sürüklemeniz yeter.",
