    // 🎞️ v0.129: mídia direta (URL ou arquivo do computador, direto para a tela)
    "Mídia direta: imagem, vídeo ou áudio de uma URL ou do computador": "Doğrudan medya: bir URL’den veya bilgisayardan görsel, video ya da ses",
    "🎞️ Mídia direta": "🎞️ Doğrudan medya",
