    "🔎 Filtrar nesta pasta": "🔎 Bu klasörde süz",
    "Mostra só as pastas e mídias cujo nome tem o que você digitar": "Yalnızca adında yazdığınız şey geçen klasörleri ve ortamları gösterir",
    "O que esta pasta tem": "Bu klasörde ne var",
    "Nada com esse nome nesta pasta.": "Bu klasörde o adda bir şey yok.",
    "Nenhuma imagem, vídeo ou áudio nesta pasta — abra uma das pastas acima.": "Bu klasörde görsel, video veya ses yok — yukarıdaki klasörlerden birini açın.",
    "Nenhuma imagem, vídeo ou áudio nesta pasta.": "Bu klasörde görsel, video veya ses yok.",
    "📂 Arquivos do computador só podem ser escolhidos no painel aberto no próprio computador do streamer — pela rede, use uma URL.": "📂 Bilgisayardaki dosyalar yalnızca yayıncının kendi bilgisayarında açılan panelde seçilebilir — ağ üzerinden bir URL kullanın.",
    "Tirar a mídia da tela e esquecer o item": "Medyayı ekrandan kaldır ve öğeyi unut",
    "A prévia aqui no painel nasce muda para o som não dobrar com a cena do OBS — marque para ouvir neste navegador": "Paneldeki önizleme, sesin OBS sahnesiyle ikilenmemesi için sessiz başlar — bu tarayıcıda duymak için işaretle",
    "🔈 ouvir aqui": "🔈 burada dinle",
    "Quando acabar, recomeça sozinha na tela do público": "Bitince izleyici ekranında kendiliğinden yeniden başlar",
    "🔁 Repetir": "🔁 Tekrarla",
    "▶️ O player é do próprio site — daqui dá só para mostrar/tirar, tamanho e tela cheia.": "▶️ Oynatıcı sitenin kendisine ait — buradan yalnızca göster/kaldır, boyut ve tam ekran yapılabilir.",
    "Cole uma URL (YouTube, TikTok, Instagram, X, Vimeo, clipe da Twitch, anexo do Discord ou o link direto de um arquivo) ou aponte um arquivo do seu computador. Nada é enviado para a biblioteca de mídias. O público vê na cena do OBS (overlay); a prévia aqui é só para você acompanhar.": "Bir URL (YouTube, TikTok, Instagram, X, Vimeo, Twitch klibi, Discord eki veya bir dosyanın doğrudan bağlantısı) yapıştır ya da bilgisayarındaki bir dosyayı göster. Medya kütüphanesine hiçbir şey gönderilmez. İzleyici OBS sahnesinde (overlay) görür; buradaki önizleme yalnızca senin takip etmen için.",
    "na tela": "ekranda",
    "carregada": "yüklendi",
    "Nenhuma mídia carregada ainda.": "Henüz medya yüklenmedi.",
    "⏳ Conferindo o que há nessa URL…": "⏳ O URL’de ne olduğuna bakılıyor…",
